&lt;li style=&quot;font-size: 12pt;&quot; data-stringify-indent=&quot;0&quot; data-stringify-border=&quot;0&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;flexible paid time off&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 12pt;&quot; data-stringify-indent=&quot;0&quot; data-stringify-border=&quot;0&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;flexible working hours (we are&amp;nbsp;&lt;a class=&quot;c-link&quot; href=&quot;https://remote.com/async&quot; target=&quot;_blank&quot; data-stringify-link=&quot;https://www.notion.so/remotecom/Working-Async-at-Remote-80c01cd443ad4c77a8ceaef7c5fba5d0&quot; data-sk=&quot;tooltip_parent&quot;&gt;async&lt;/a&gt;)&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 12pt;&quot; data-stringify-indent=&quot;0&quot; data-stringify-border=&quot;0&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;16 weeks paid parental leave&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 12pt;&quot; data-stringify-indent=&quot;0&quot; data-stringify-border=&quot;0&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;budget towards &lt;a href=&quot;https://app.notion.com/p/remotecom/Benefits-Perks-1e48a5869c274f40910b76d405b92f63?source=copy_link#3accb4dadab48025b7a6dbc23bc47504&quot; target=&quot;_blank&quot;&gt;co-working spaces, learning and wellness&lt;/a&gt; (including gym memberships)&lt;/span&gt;&lt;/li&gt;
